construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>

CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/72/7554> .
  ?publication dblp:authoredBy ?coAuthor .
}
WHERE {
  ?publication dblp:authoredBy <https://dblp.org/pid/72/7554> .
  ?publication dblp:authoredBy ?coAuthor .
  FILTER (?coAuthor != <https://dblp.org/pid/72/7554>)
}

