construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
CONSTRUCT {
    ?paper dblp:authoredBy <https://dblp.org/pid/04/5689> .
    ?paper dblp:yearOfPublication ?year .
}
WHERE {
    ?paper dblp:authoredBy <https://dblp.org/pid/04/5689> .
    ?paper dblp:yearOfPublication ?year .
    FILTER(xsd:integer(?year) >= (YEAR(NOW()) - 6))
}

