construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?paper dblp:authoredBy <https://dblp.org/pid/70/1586> .
    ?paper dblp:authoredBy ?coAuthor .
    ?paper dblp:yearOfPublication ?year .
    ?coAuthor dblp:affiliation ?affiliation .
}
WHERE {
    ?paper dblp:authoredBy <https://dblp.org/pid/70/1586> ;
           dblp:yearOfPublication ?year ;
           dblp:authoredBy ?coAuthor .
    FILTER(xsd:integer(?year) >= (YEAR(NOW()) - 8))
    FILTER(?coAuthor != <https://dblp.org/pid/70/1586>)
    OPTIONAL {
        ?coAuthor dblp:affiliation ?affiliation .
    }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
CONSTRUCT {
    ?publication dblp:authoredBy <https://dblp.org/pid/183/1235> .
    ?publication dblp:authoredBy ?coauthor .
    ?coauthor dblp:primaryAffiliation ?affiliation .
}
WHERE {
    ?publication dblp:authoredBy <https://dblp.org/pid/183/1235> .
    ?publication dblp:authoredBy ?coauthor .
    FILTER(?coauthor != <https://dblp.org/pid/183/1235>)
    OPTIONAL {
        ?coauthor dblp:primaryAffiliation ?affiliation .
    }
}

CONSTRUCT {
  ?publication dblp:authoredBy ?co_author .
  ?publication dblp:yearOfPublication ?year .
}
