CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/64/10830> .
  ?publication dblp:authoredBy ?coAuthor .
  ?coAuthor dblp:primaryAffiliation ?affiliation .
}
WHERE {
  ?publication dblp:authoredBy <https://dblp.org/pid/64/10830> .
  ?publication dblp:authoredBy ?coAuthor .
  FILTER(?coAuthor != <https://dblp.org/pid/64/10830>)
  OPTIONAL {
    ?coAuthor dblp:primaryAffiliation ?affiliation .
  }
}

