construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
    <https://dblp.org/pid/181/1768> dblp:authoredBy ?publication .
    ?publication dblp:yearOfPublication ?year .
}
WHERE {
    ?publication dblp:authoredBy <https://dblp.org/pid/181/1768> .
    ?publication dblp:yearOfPublication ?year .
    FILTER (?year = "2016"^^xsd:gYear)
}

