construct_query:
CONSTRUCT {
    ?paper1 dblp:authoredBy <https://dblp.org/pid/150/9073> .
    ?paper2 dblp:authoredBy <https://dblp.org/pid/41/3106> .
}
WHERE {
    ?paper1 a dblp:Publication .
    ?paper2 a dblp:Publication .
    ?paper1 dblp:authoredBy <https://dblp.org/pid/150/9073> .
    ?paper2 dblp:authoredBy <https://dblp.org/pid/41/3106> .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?paper a dblp:Publication ;
         dblp:authoredBy <https://dblp.org/pid/211/6758> ;
         dblp:publishedIn ?venueName ;
         dblp:title ?title .
  <https://dblp.org/pid/211/6758> dblp:creatorName ?authorName .
}
WHERE {
  ?paper dblp:authoredBy <https://dblp.org/pid/211/6758> ;
         dblp:publishedIn ?venueName ;
         dblp:title ?title .
  <https://dblp.org/pid/211/6758> dblp:creatorName ?authorName .
  FILTER (?venueName = "AIM" || ?venueName = "World Wide Web")
}

