construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?author a dblp:Creator ;
          dblp:creatorName ?authorName .
  <https://dblp.org/rec/journals/sensors/BarbulescuD22> a dblp:Publication ;
                                                        dblp:title ?paperTitle .
  <https://dblp.org/rec/journals/sensors/BarbulescuD22> dblp:authoredBy ?author .
}
WHERE {
  <https://dblp.org/rec/journals/sensors/BarbulescuD22> dblp:authoredBy ?author ;
                                                        dblp:title ?paperTitle .
  ?author dblp:creatorName ?authorName .

  FILTER (CONTAINS(LCASE(STR(?authorName)), "barbulescu"))
  FILTER (CONTAINS(LCASE(STR(?paperTitle)), "intelligence methods"))
}

