PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?paper a dblp:Publication ;
           dblp:title ?title ;
           dblp:authoredBy <https://dblp.org/pid/45/4076> ;
           dblp:publishedIn ?venue .
}
WHERE {
    ?paper dblp:authoredBy <https://dblp.org/pid/45/4076> .
    ?paper dblp:publishedIn ?venue .
    FILTER (?venue = "Complex.") .
    ?paper dblp:title ?title .
    FILTER (CONTAINS(LCASE(STR(?title)), LCASE("Network features"))) .
    ?paper a dblp:Publication .
}

