construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    <https://dblp.org/pid/63/956> schema:about _:b0 .
    _:b0 a schema:QuantitativeValue ;
         rdfs:label "Average number of co-authors" ;
         schema:value ?avgCoAuthors ;
         schema:unitText "co-authors" .
}
WHERE {
    SELECT (AVG(?numCreators - 1) AS ?avgCoAuthors)
    WHERE {
        ?publication dblp:authoredBy <https://dblp.org/pid/63/956> .
        ?publication dblp:numberOfCreators ?numCreators .
    }
}

