construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  _:avgCoAuthorsResult a schema:QuantitativeValue ;
                       schema:value ?averageCoAuthors ;
                       rdfs:label "Average number of co-authors for publications by David W. K. Yeung" .
}
WHERE {
  SELECT (AVG(?totalCreators - 1) AS ?averageCoAuthors)
  WHERE {
    <https://dblp.org/pid/06/2724> dblp:authorOf ?publication .
    ?publication dblp:numberOfCreators ?totalCreators .
  }
}

