construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  _:avgResult schema:value ?averagePapers ;
              rdfs:label "Average number of research papers published by M. J. Cresswell per year" .
}
WHERE {
  {
    SELECT (AVG(?papersPerYear) AS ?averagePapers)
    WHERE {
      {
        SELECT ?year (COUNT(?publication) AS ?papersPerYear)
        WHERE {
          <https://dblp.org/pid/c/MJCresswell> dblp:authorOf ?publication .
          ?publication dblp:yearOfPublication ?year .
        }
        GROUP BY ?year
      }
    }
  }
}

