construct_query:
CONSTRUCT {
    ?publication dblp:authoredBy <https://dblp.org/pid/306/8179> .
    ?publication dblp:authoredBy ?co_author .
}
WHERE {
    ?publication dblp:authoredBy <https://dblp.org/pid/306/8179> .
    ?publication dblp:authoredBy ?co_author .
}

CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/96/9408> .
  ?publication dblp:authoredBy ?co_author .
}
WHERE {
  {
    SELECT ?co_author (COUNT(?publication) AS ?count)
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/96/9408> .
      ?publication dblp:authoredBy ?co_author .
    }
    GROUP BY ?co_author
    ORDER BY DESC(?count)
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/96/9408> .
  ?publication dblp:authoredBy ?co_author .
}

