construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/09/3508> .
  ?publication dblp:publishedIn ?venue .
}
WHERE {
  {
    SELECT ?venue
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/09/3508> .
      ?publication dblp:publishedIn ?venue .
