construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    <https://dblp.org/pid/55/1226> dblp:authoredBy ?publication .
    ?publication dblp:yearOfPublication ?yearWithMostPublications .
}
WHERE {
    {
        SELECT ?yearWithMostPublications
        WHERE {
            ?publication_inner dblp:authoredBy <https://dblp.org/pid/55/1226> .
            ?publication_inner dblp:yearOfPublication ?yearWithMostPublications .
        }
        GROUP BY ?yearWithMostPublications
        ORDER BY DESC(COUNT(?publication_inner))
        LIMIT 1
    }
    ?publication dblp:authoredBy <https://dblp.org/pid/55/1226> .
    ?publication dblp:yearOfPublication ?yearWithMostPublications .
}

