PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  _:b0 a schema:Answer ;
       schema:about <https://dblp.org/pid/93/4824> ;
       schema:value ?yearWithMostPublications .
}
WHERE {
  {
    SELECT ?year (COUNT(?publication) AS ?publicationCount)
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/93/4824> ;
                   dblp:yearOfPublication ?year .
    }
    GROUP BY ?year
    ORDER BY DESC(?publicationCount)
    LIMIT 1
  }
  BIND(?year AS ?yearWithMostPublications)
}

