construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?mostFrequentCoAuthor dblp:creatorName ?coAuthorName .
  ?publication dblp:authoredBy ?mostFrequentCoAuthor ;
               dblp:authoredBy <https://dblp.org/pid/169/2015> ;
               dblp:title ?publicationTitle .
}
WHERE {
  BIND(<https://dblp.org/pid/169/2015> AS ?mitraAritra)

  {
    SELECT ?coAuthor (COUNT(DISTINCT ?pub) AS ?coAuthorCount)
    WHERE {
      ?pub dblp:authoredBy ?mitraAritra .
      ?pub dblp:authoredBy ?coAuthor .
      FILTER (?coAuthor != ?mitraAritra)
    }
    GROUP BY ?coAuthor
    ORDER BY DESC(?coAuthorCount)
    LIMIT 1
  }
  BIND(?coAuthor AS ?mostFrequentCoAuthor)

  ?mostFrequentCoAuthor dblp:creatorName ?coAuthorName .

  ?publication dblp:authoredBy ?mitraAritra ;
               dblp:authoredBy ?mostFrequentCoAuthor .

  OPTIONAL { ?publication dblp:title ?publicationTitle . }
}

