construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    <https://dblp.org/pid/f/RonaldFedkiw> dblp:authoredBy ?publication .
    ?publication dblp:yearOfPublication ?minYear .
}
WHERE {
    {
        SELECT (MIN(?year) AS ?minYear)
        WHERE {
            ?tempPublication dblp:authoredBy <https://dblp.org/pid/f/RonaldFedkiw> .
            ?tempPublication dblp:yearOfPublication ?year .
        }
    }
    ?publication dblp:authoredBy <https://dblp.org/pid/f/RonaldFedkiw> .
    ?publication dblp:yearOfPublication ?minYear .
}

