construct_query:
CONSTRUCT {
    ?paper a dblp:Publication .
    ?paper dblp:authoredBy <https://dblp.org/pid/190/0150> .
    ?paper dblp:authoredBy ?co_author .
    ?co_author a dblp:Creator .
}
WHERE {
    {
        SELECT ?co_author
        WHERE {
            ?paper dblp:authoredBy <https://dblp.org/pid/190/0150> .
            ?paper dblp:authoredBy ?co_author .
        }
        GROUP BY ?co_author
        ORDER BY DESC(COUNT(?paper))
        LIMIT 1
    }
    ?paper a dblp:Publication .
    ?paper dblp:authoredBy <https://dblp.org/pid/190/0150> .
    ?paper dblp:authoredBy ?co_author .
    ?co_author a dblp:Creator .
}

