  ?publication dblp:authoredBy <https://dblp.org/pid/96/1406> .
  ?publication dblp:yearOfPublication ?year .
}
WHERE {
  {
    SELECT ?year WHERE {
      ?publication_sub dblp:authoredBy <https://dblp.org/pid/96/1406> .
      ?publication_sub dblp:yearOfPublication ?year .
    }
    GROUP BY ?year
    ORDER BY DESC(COUNT(?publication_sub))
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/96/1406> .
  ?publication dblp:yearOfPublication ?year .
}

