construct_query:
CONSTRUCT {
    ?publication dblp:authoredBy <https://dblp.org/pid/64/6611> .
    ?publication dblp:yearOfPublication ?yearOfPublication .
}
WHERE {
    {
        SELECT ?yearOfPublication WHERE {
            {
                SELECT ?yearOfPublication (COUNT(?publication) AS ?count)
                WHERE {
                    ?publication dblp:authoredBy <https://dblp.org/pid/64/6611> .
                    ?publication dblp:yearOfPublication ?yearOfPublication .
                }
                GROUP BY ?yearOfPublication
                ORDER BY DESC(?count)
                LIMIT 1
            }
        }
    }
    ?publication dblp:authoredBy <https://dblp.org/pid/64/6611> .
    ?publication dblp:yearOfPublication ?yearOfPublication .
}

