construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/15/6162> .
  ?publication dblp:yearOfPublication ?year .
}
WHERE {
  ?publication dblp:authoredBy <https://dblp.org/pid/15/6162> .
  ?publication dblp:yearOfPublication ?year .
  {
    SELECT (MIN(?year_inner) AS ?year)
    WHERE {
      ?publication_inner dblp:authoredBy <https://dblp.org/pid/15/6162> .
      ?publication_inner dblp:yearOfPublication ?year_inner .
    }
  }
}

subgraph_ttl:
@prefix dblp: <https://dblp.org/rdf/schema#> .

<https://dblp.org/rec/conf/hci/MaggioniR99> dblp:authoredBy <https://dblp.org/pid/15/6162> ;
    dblp:yearOfPublication "1999" .

construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  _:mostFrequentVenue rdfs:label ?venueName .
}
WHERE {
  {
    SELECT ?venueName (COUNT(?publication) AS ?publicationCount)
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/f/ToshioFukuda> .
      ?publication dblp:publishedIn ?venueName .
    }
    GROUP BY ?venueName
    ORDER BY DESC(?publicationCount)
    LIMIT 1
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
  <https://dblp.org/pid/37/1629-21> dblp:coAuthorWith ?mostFrequentCoAuthor .
  ?mostFrequentCoAuthor dblp:creatorName ?coAuthorName .
  _:result rdfs:label ?resultLabel ;
           rdf:value ?maxCount ;
           dblp:coAuthorWith ?mostFrequentCoAuthor .
}
WHERE {
  BIND(<https://dblp.org/pid/37/1629-21> AS ?linZhang)

  {
    SELECT ?coAuthor (COUNT(DISTINCT ?publication) AS ?paperCount)
    WHERE {
      ?publication dblp:authoredBy ?linZhang .
      ?publication dblp:authoredBy ?coAuthor .
      FILTER (?coAuthor != ?linZhang)
    }
    GROUP BY ?coAuthor
    ORDER BY DESC(?paperCount)
    LIMIT 1
  }
  BIND(?coAuthor AS ?mostFrequentCoAuthor)
  BIND(?paperCount AS ?maxCount)
  ?mostFrequentCoAuthor dblp:creatorName ?coAuthorName .
  BIND(CONCAT("Has co-authored ", STR(?maxCount), " papers with Lin Zhang") AS ?resultLabel)
}

