construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
    <https://dblp.org/pid/146/5966> dblp:primaryCreatorName ?authorName .
    <https://dblp.org/pid/146/5966> dblp:creatorNote ?mostPublishedVenueDescription .
}
WHERE {
    BIND(<https://dblp.org/pid/146/5966> AS ?author)
    ?author dblp:primaryCreatorName ?authorName .

    {
        SELECT ?venueName (COUNT(?publication) AS ?pubCount)
        WHERE {
            ?publication dblp:authoredBy ?author .
            ?publication dblp:publishedIn ?venueName .
        }
        GROUP BY ?venueName
        ORDER BY DESC(?pubCount)
        LIMIT 1
    }
    BIND(CONCAT("Most publications in: ", ?venueName, " (", STR(?pubCount), " publications)") AS ?mostPublishedVenueDescription)
}

