construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?answer a schema:Answer ;
            schema:about <https://dblp.org/pid/190/7423> ;
            schema:result ?coAuthor ;
            schema:name ?coAuthorName ;
            schema:value ?coPublicationCount .
}
WHERE {
    BIND(<https://dblp.org/pid/190/7423> AS ?petrV)
    {
        SELECT ?coAuthor (COUNT(DISTINCT ?publication) AS ?coPublicationCount)
        WHERE {
            ?publication dblp:authoredBy ?petrV .
            ?publication dblp:authoredBy ?coAuthor .
            FILTER (?coAuthor != ?petrV)
        }
        GROUP BY ?coAuthor
        ORDER BY DESC(?coPublicationCount)
        LIMIT 1
    }
    ?coAuthor dblp:primaryCreatorName ?coAuthorName .
    BIND(BNODE() AS ?answer)
}

