construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/62/6794> .
  ?publication dblp:publishedIn ?venue .
}
WHERE {
  {
    SELECT ?venue
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/62/6794> .
      ?publication dblp:publishedIn ?venue .
    }
    GROUP BY ?venue
    ORDER BY DESC(COUNT(?publication))
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/62/6794> .
  ?publication dblp:publishedIn ?venue .
}

