construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/10/5630> .
  ?publication dblp:yearOfPublication ?year .
}
WHERE {
  {
    SELECT ?year
    WHERE {
      ?publication dblp:authoredBy <https://dblp.org/pid/10/5630> .
      ?publication dblp:yearOfPublication ?year .
    }
    GROUP BY ?year
    ORDER BY DESC(COUNT(?publication))
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/10/5630> .
  ?publication dblp:yearOfPublication ?year .
}

