      ?publication dblp:publishedIn ?venue .
    }
    GROUP BY ?venue
    ORDER BY DESC(?count)
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/46/999-1> .
  ?publication dblp:publishedIn ?venue .
}

