    GROUP BY ?venue
    ORDER BY DESC(COUNT(?publication))
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/246/3262> .
  ?publication dblp:publishedIn ?venue .
}

