construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    <https://dblp.org/pid/188/4447> dblp:authoredBy ?publication .
    ?publication dblp:yearOfPublication ?year .
}
WHERE {
    {
        SELECT ?year (COUNT(?p) AS ?publicationCount)
        WHERE {
            ?p dblp:authoredBy <https://dblp.org/pid/188/4447> .
            ?p dblp:yearOfPublication ?year .
        }
        GROUP BY ?year
        ORDER BY DESC(?publicationCount)
        LIMIT 1
    }
    ?publication dblp:authoredBy <https://dblp.org/pid/188/4447> .
    ?publication dblp:yearOfPublication ?year .
}

