construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy <https://dblp.org/pid/98/3883> .
  ?publication dblp:yearOfPublication ?year .
}
WHERE {
  {
    SELECT ?year WHERE {
      {
        SELECT ?year (COUNT(?publication_inner) AS ?count) WHERE {
          ?publication_inner dblp:authoredBy <https://dblp.org/pid/98/3883> .
          ?publication_inner dblp:yearOfPublication ?year .
        }
        GROUP BY ?year
        ORDER BY ASC(?count)
        LIMIT 1
      }
    }
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/98/3883> .
  ?publication dblp:yearOfPublication ?year .
}

