    <https://dblp.org/pid/73/2715> dblp:authorOf ?latestPublication .
    ?latestPublication dblp:yearOfPublication ?maxYear .
}
WHERE {
    ?latestPublication dblp:authoredBy <https://dblp.org/pid/73/2715> .
    ?latestPublication dblp:yearOfPublication ?maxYear .
}
ORDER BY DESC(?maxYear)
LIMIT 1

