construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  _:answer schema:name ?venueName .
}
WHERE {
  SELECT ?venueName (COUNT(?publication) AS ?pubCount)
  WHERE {
    ?publication dblp:authoredBy <https://dblp.org/pid/131/7641> ;
                 dblp:publishedIn ?venueName .
  }
  GROUP BY ?venueName
  ORDER BY DESC(?pubCount)
  LIMIT 1
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  <https://dblp.org/pid/68/164> dblp:authoredBy ?publication .
  ?publication dblp:yearOfPublication ?mostProductiveYear .
}
WHERE {
  {
    SELECT ?mostProductiveYear
    WHERE {
      ?p dblp:authoredBy <https://dblp.org/pid/68/164> .
      ?p dblp:yearOfPublication ?mostProductiveYear .
    }
    GROUP BY ?mostProductiveYear
    ORDER BY DESC(COUNT(?p))
    LIMIT 1
  }
  ?publication dblp:authoredBy <https://dblp.org/pid/68/164> .
  ?publication dblp:yearOfPublication ?mostProductiveYear .
}

