construct_query:
CONSTRUCT {
    ?publication dblp:authoredBy <https://dblp.org/pid/s/JoelHSpencer> .
    ?publication dblp:publishedIn ?venue .
}
WHERE {
    {
        SELECT ?venue (COUNT(?publication) AS ?count)
        WHERE {
            ?publication dblp:authoredBy <https://dblp.org/pid/s/JoelHSpencer> .
            ?publication dblp:publishedIn ?venue .
        }
        GROUP BY ?venue
        ORDER BY DESC(?count)
        LIMIT 1
    }
    ?publication dblp:authoredBy <https://dblp.org/pid/s/JoelHSpencer> .
    ?publication dblp:publishedIn ?venue .
}

