construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?otherPublication rdf:type ?publicationType ;
                    dblp:title ?publicationTitle ;
                    dblp:authoredBy ?author .
  ?author dblp:primaryCreatorName ?authorName .
}
WHERE {
  # Find the authors of the specified publication
  <https://dblp.org/rec/conf/coling/ZernikJ90> dblp:authoredBy ?author .

  # Find all publications authored by these authors
  ?otherPublication dblp:authoredBy ?author .

  # Exclude the original publication itself
  FILTER (?otherPublication != <https://dblp.org/rec/conf/coling/ZernikJ90>) .

  # Get details for the other publications and authors (optional to ensure results even if some data is missing)
  OPTIONAL { ?otherPublication rdf:type ?publicationType . }
  OPTIONAL { ?otherPublication dblp:title ?publicationTitle . }
  OPTIONAL { ?author dblp:primaryCreatorName ?authorName . }
}

