construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?otherPublication dblp:title ?otherPublicationTitle ;
                      rdf:type ?otherPublicationType ;
                      dblp:authoredBy ?author .
    ?author dblp:creatorName ?authorName .
}
WHERE {
    # 1. Get authors of the specified publication
    <https://dblp.org/rec/journals/tnn/RobinsonAS05> dblp:authoredBy ?author .

    # 2. Get other publications authored by these authors
    ?otherPublication dblp:authoredBy ?author .

    # 3. Exclude the original publication
    FILTER (?otherPublication != <https://dblp.org/rec/journals/tnn/RobinsonAS05>) .

    # 4. Get details for the other publications and the author's name
    OPTIONAL { ?otherPublication dblp:title ?otherPublicationTitle . }
    OPTIONAL { ?otherPublication rdf:type ?otherPublicationType . }
    OPTIONAL { ?author dblp:creatorName ?authorName . }
}

