construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  <https://dblp.org/rec/journals/scp/MengS12> dblp:authoredBy ?author .
  ?author dblp:primaryAffiliation ?affiliation .
}
WHERE {
  <https://dblp.org/rec/journals/scp/MengS12> dblp:authoredBy ?author .
  OPTIONAL { ?author dblp:primaryAffiliation ?affiliation . }
}

CONSTRUCT {
  <https://dblp.org/rec/conf/aiam/ZhouL21> dblp:authoredBy ?author .
  ?other_paper dblp:authoredBy ?author .
  ?other_paper dblp:publishedIn ?venue .
}
WHERE {
  <https://dblp.org/rec/conf/aiam/ZhouL21> dblp:authoredBy ?author .
  ?other_paper dblp:authoredBy ?author .
  ?other_paper dblp:publishedIn ?venue .
}

