construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
    <https://dblp.org/rec/conf/jcdcg/AbelADDHKKL18> dblp:yearOfPublication ?year .
}
WHERE {
    <https://dblp.org/rec/conf/jcdcg/AbelADDHKKL18> dblp:yearOfPublication ?year .
    FILTER (?year = "2021"^^xsd:gYear)
}

