construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX bibtex: <http://purl.org/net/nknouf/ns/bibtex#>

CONSTRUCT {
  <https://dblp.org/rec/journals/ijon/BohnsackDKLV16> dblp:bibtexType bibtex:Article .
}
WHERE {
  <https://dblp.org/rec/journals/ijon/BohnsackDKLV16> dblp:bibtexType bibtex:Article .
}

CONSTRUCT {
    <https://dblp.org/rec/journals/dm/MatsonR18>  dblp:authoredBy ?author .
    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
}
WHERE {
    <https://dblp.org/rec/journals/dm/MatsonR18>  dblp:authoredBy ?author .
    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
}

