    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
}
WHERE {
    <https://dblp.org/rec/journals/taslp/AudhkhasiZGN14> dblp:authoredBy ?author .
    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
}

CONSTRUCT { <https://dblp.org/rec/conf/uist/DesaiMC18> dblp:authoredBy ?x1 . <https://dblp.org/rec/journals/bc/GlavinovicGAT08> dblp:authoredBy ?x2 . ?x1 a dblp:Creator . ?x2 a dblp:Creator . }
WHERE {
  <https://dblp.org/rec/conf/uist/DesaiMC18> a dblp:Publication ;
                                           dblp:authoredBy ?x1 .
  <https://dblp.org/rec/journals/bc/GlavinovicGAT08> dblp:authoredBy ?x2 .
  ?x1 a dblp:Creator .
  ?x2 a dblp:Creator .
}

CONSTRUCT { ?x ?p ?o . }
WHERE {
  <https://dblp.org/rec/journals/tip/JoshiSTL09> dblp:authoredBy ?x .
  ?x ?p ?o .
}

