construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  <https://dblp.org/rec/conf/wcsc/BedeR13> dblp:authoredBy ?author1 .
  ?author1 rdf:type dblp:Creator .
  ?author1 dblp:creatorName ?name1 .

  <https://dblp.org/rec/conf/sspr/ImiyaHT02> dblp:authoredBy ?author2 .
  ?author2 rdf:type dblp:Creator .
  ?author2 dblp:creatorName ?name2 .
}
WHERE {
  # Get authors of the first publication
  <https://dblp.org/rec/conf/wcsc/BedeR13> dblp:authoredBy ?author1 .
  OPTIONAL { ?author1 rdf:type dblp:Creator . }
  OPTIONAL { ?author1 dblp:creatorName ?name1 . }

  # Get authors of the second publication
  <https://dblp.org/rec/conf/sspr/ImiyaHT02> dblp:authoredBy ?author2 .
  OPTIONAL { ?author2 rdf:type dblp:Creator . }
  OPTIONAL { ?author2 dblp:creatorName ?name2 . }
}

