construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  <https://dblp.org/rec/journals/corr/abs-2003-04792> dblp:authoredBy ?author .
  ?author dblp:creatorName ?authorName .
  ?otherPublication dblp:publishedIn "CoRR" .
  ?otherPublication dblp:title ?otherPublicationTitle .
  <urn:answer> <urn:result> ?answerValue .
}
WHERE {
  BIND(<https://dblp.org/rec/journals/corr/abs-2003-04792> AS ?initialPublication)

  # Get all authors of the initial publication
  ?initialPublication dblp:authoredBy ?author .
  OPTIONAL { ?author dblp:creatorName ?authorName . }

  # Check if any of these authors have published in CoRR
  {
    SELECT (EXISTS {
      ?initialPublication dblp:authoredBy ?a .
      ?a dblp:authorOf ?p .
      ?p dblp:publishedIn "CoRR" .
    } AS ?hasCoRRPub)
    WHERE {
      BIND(<https://dblp.org/rec/journals/corr/abs-2003-04792> AS ?initialPublication)
    }
  }

  # Determine the boolean answer for "Did they NOT publish in CoRR?"
  # If ?hasCoRRPub is true, then the answer to "did they NOT publish" is false.
  # If ?hasCoRRPub is false, then the answer to "did they NOT publish" is true.
  BIND(IF(?hasCoRRPub, false, true) AS ?answerValue)

  # Conditionally include the CoRR publications if they exist (i.e., ?hasCoRRPub is true)
  OPTIONAL {
    FILTER(?hasCoRRPub)
    ?author dblp:authorOf ?otherPublication .
    ?otherPublication dblp:publishedIn "CoRR" .
    OPTIONAL { ?otherPublication dblp:title ?otherPublicationTitle . }
  }
}

