construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    <https://dblp.org/rec/journals/corr/abs-cs-0611103> dblp:authoredBy ?author .
}
WHERE {
    <https://dblp.org/rec/journals/corr/abs-cs-0611103> dblp:authoredBy ?author .

    FILTER NOT EXISTS {
        ?author dblp:authorOf ?publication_by_author .
        ?publication_by_author dblp:publishedIn "CoRR" .
    }
}

CONSTRUCT {
  <https://dblp.org/rec/journals/ijgs/PoelmansIKD14> dblp:yearOfPublication ?year .
}
WHERE {
  <https://dblp.org/rec/journals/ijgs/PoelmansIKD14> dblp:yearOfPublication ?year .
}

CONSTRUCT {
  ?publication dblp:yearOfPublication ?yearOfPublication .
}
WHERE {
  VALUES ?publication { <https://dblp.org/rec/journals/sigact/ORourke04> }
  ?publication dblp:yearOfPublication ?yearOfPublication .
}

CONSTRUCT {
  <https://dblp.org/rec/journals/corr/GeZXLW16> dblp:authoredBy ?author .
  ?publication dblp:authoredBy ?author .
  ?publication dblp:publishedIn ?venue .
}
WHERE {
  <https://dblp.org/rec/journals/corr/GeZXLW16> dblp:authoredBy ?author .
  ?publication dblp:authoredBy ?author .
  ?publication dblp:publishedIn ?venue .
}

