PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
  ?author a dblp:Creator ;
          dblp:creatorName ?authorName .
  ?publication a dblp:Publication ;
               dblp:authoredBy ?author ;
               dblp:title ?title ;
               dblp:publishedInJournal ?journalName ;
               dblp:yearOfPublication ?year .
}
WHERE {
  ?publication a dblp:Publication .
  ?publication dblp:yearOfPublication "1994"^^xsd:gYear .
  ?publication dblp:publishedInJournal ?journalName .
  FILTER (STR(?journalName) = "J. Inf. Syst. Educ.")
  ?publication dblp:title ?title .
  FILTER (CONTAINS(LCASE(STR(?title)), "information systems"))
  ?publication dblp:authoredBy ?author .
  ?author dblp:creatorName ?authorName .
}

