construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
    ?author a dblp:Creator ;
            dblp:creatorName ?authorName .
    ?publication a dblp:Publication ;
                 dblp:title ?publicationTitle ;
                 dblp:publishedInJournal "Microelectron. J." ;
                 dblp:yearOfPublication "2015"^^xsd:gYear ;
                 dblp:authoredBy ?author .
}
WHERE {
    ?publication dblp:publishedInJournal "Microelectron. J." .
    ?publication dblp:yearOfPublication "2015"^^xsd:gYear .
    ?publication dblp:title ?publicationTitle .
    FILTER (CONTAINS(LCASE(?publicationTitle), LCASE("Rx mimo"))) .
    ?publication dblp:authoredBy ?author .
    ?author dblp:creatorName ?authorName .
}

