construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?author a dblp:Creator ;
            dblp:primaryCreatorName ?authorName .
}
WHERE {
    ?publication a dblp:Publication ;
                 dblp:title ?title ;
                 dblp:publishedInJournal "Eng. Appl. Artif. Intell." ;
                 dblp:yearOfPublication "2012"^^xsd:gYear ;
                 dblp:authoredBy ?author .
    ?author dblp:primaryCreatorName ?authorName .
    FILTER (CONTAINS(LCASE(?title), LCASE("Workflow systems")))
}

