CONSTRUCT {
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:authoredBy ?creator .
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:publishedIn ?string .
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:yearOfPublication ?gYear .
}
WHERE {
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:authoredBy ?creator .
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:publishedIn ?string .
  <https://dblp.org/rec/journals/fgcs/SasPR05> dblp:yearOfPublication ?gYear .
}

