construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
  ?paper rdf:type dblp:Publication ;
         dblp:title ?title ;
         dblp:publishedIn ?venueName ;
         dblp:yearOfPublication ?year .
}
WHERE {
  ?paper rdf:type dblp:Publication .
  ?paper dblp:title ?title .
  ?paper dblp:publishedIn ?venueName .
  ?paper dblp:yearOfPublication ?year .

  FILTER (CONTAINS(LCASE(?venueName), LCASE("ICIRA (1)")))
  FILTER (?year = "2021"^^xsd:gYear)
  FILTER (CONTAINS(LCASE(?title), LCASE("Contract ratio")))
}

