construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?author a dblp:Creator ;
          dblp:creatorName ?authorName .
  ?publication a dblp:Publication ;
               dblp:title ?title ;
               dblp:yearOfPublication ?year ;
               dblp:publishedIn ?venue ;
               dblp:authoredBy ?author .
}
WHERE {
  ?publication dblp:yearOfPublication "1993"^^xsd:gYear ;
               dblp:publishedIn "AADEBUG" ;
               dblp:title ?title ;
               dblp:authoredBy ?author .
  ?author dblp:creatorName ?authorName .
  FILTER (CONTAINS(LCASE(STR(?title)), "software maintenance")) .
  BIND("1993"^^xsd:gYear AS ?year)
  BIND("AADEBUG" AS ?venue)
}

