construct_query:
CONSTRUCT {
  ?publication dblp:authoredBy ?creator .
  ?creator dblp:primaryAffiliation ?affiliation .
  ?publication dblp:yearOfPublication ?year .
}
WHERE {
  VALUES ?publication { <https://dblp.org/rec/conf/cvpr/GuiTP07> }
  ?publication dblp:authoredBy ?creator .
  ?creator dblp:primaryAffiliation ?affiliation .
  ?publication dblp:yearOfPublication ?year .
}

