construct_query:
CONSTRUCT {
    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
    ?publication dblp:yearOfPublication ?year .
}
WHERE {
    VALUES ?publication { <https://dblp.org/rec/journals/electronicmarkets/KollmannHCS20> }
    ?publication dblp:authoredBy ?author .
    ?publication dblp:publishedIn ?venue .
    ?publication dblp:yearOfPublication ?year .
}

