construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?author a dblp:Creator ;
            dblp:creatorName ?authorName ;
            dblp:authorOf ?publication .
    ?publication a dblp:Publication ;
                 dblp:title ?title ;
                 dblp:publishedInJournal ?journal ;
                 dblp:yearOfPublication ?year .
}
WHERE {
    ?publication a dblp:Publication .
    ?publication dblp:publishedInJournal ?journal .
    FILTER (?journal = "J. Cell. Autom.") .
    ?publication dblp:yearOfPublication ?year .
    FILTER (?year = "2021"^^xsd:gYear) .
    ?publication dblp:title ?title .
    FILTER (CONTAINS(LCASE(?title), LCASE("Register machine"))) .
    ?publication dblp:authoredBy ?author .
    ?author dblp:creatorName ?authorName .
}

