construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
    ?author rdf:type dblp:Creator ;
            dblp:primaryCreatorName ?authorName .
    ?publication rdf:type dblp:Publication ;
                 dblp:title ?title ;
                 dblp:yearOfPublication ?year ;
                 dblp:publishedInJournal ?journalName ;
                 dblp:authoredBy ?author .
}
WHERE {
    ?publication dblp:yearOfPublication "1965"^^xsd:gYear ;
                 dblp:publishedInJournal ?journalName ;
                 dblp:title ?title ;
                 dblp:authoredBy ?author .
    ?author dblp:primaryCreatorName ?authorName .
    FILTER (?journalName = "Notre Dame J. Formal Log.")
    FILTER (regex(?title, "Theoretical formulas", "i"))
    BIND("1965"^^xsd:gYear AS ?year)
}

