PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?publication dblp:title ?title .
}
WHERE {
  ?publication dblp:publishedIn "IEEE Trans. Computers" ;
               dblp:yearOfPublication "2005"^^xsd:gYear ;
               dblp:title ?title .
