construct_query:
CONSTRUCT {
  <https://dblp.org/rec/conf/icct/XiaoLL19> dblp:authoredBy ?creator .
  ?creator dblp:primaryAffiliation ?string .
}
WHERE {
  <https://dblp.org/rec/conf/icct/XiaoLL19> dblp:authoredBy ?creator .
  OPTIONAL {?creator dblp:primaryAffiliation ?string .}
}

CONSTRUCT {
  ?paper1 dblp:authoredBy ?author .
  ?paper2 dblp:authoredBy ?author .
  ?paper1 dblp:publishedIn ?venue .
}
WHERE {
  VALUES ?paper1 { <https://dblp.org/rec/journals/cssc/Noughabi17a> }
  ?paper1 dblp:authoredBy ?author .
  ?paper2 dblp:authoredBy ?author .
  ?paper1 dblp:publishedIn ?venue .
}

CONSTRUCT {
  <https://dblp.org/rec/conf/csedu/Oliver-Quelennec21> dblp:authoredBy ?creator .
  ?publication dblp:authoredBy ?creator .
  ?publication dblp:publishedIn ?venue .
}
WHERE {
  <https://dblp.org/rec/conf/csedu/Oliver-Quelennec21> dblp:authoredBy ?creator .
  ?publication dblp:authoredBy ?creator .
  ?publication dblp:publishedIn ?venue .
}

