CONSTRUCT {
  <https://dblp.org/rec/journals/twc/LiuSC10> dblp:authoredBy ?author .
  ?publication dblp:authoredBy ?author .
}
WHERE {
  <https://dblp.org/rec/journals/twc/LiuSC10> a dblp:Publication ;
    dblp:authoredBy ?author .
  ?author a dblp:Creator .
  ?publication a dblp:Publication ;
    dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/journals/ijsda/MindilaRMM14a> dblp:authoredBy ?x1 .
  ?x2 dblp:authoredBy ?x1 .
}
WHERE {
  <https://dblp.org/rec/journals/ijsda/MindilaRMM14a> a dblp:Publication .
  <https://dblp.org/rec/journals/ijsda/MindilaRMM14a> dblp:authoredBy ?x1 .
  ?x1 a dblp:Creator .
  ?x2 dblp:authoredBy ?x1 .
  ?x2 a dblp:Publication .
}

CONSTRUCT {
  <https://dblp.org/rec/conf/ciss/EryilmazOSM08> dblp:authoredBy ?creator .
  ?creator dblp:primaryAffiliation ?string .
}
WHERE {
  <https://dblp.org/rec/conf/ciss/EryilmazOSM08> dblp:authoredBy ?creator .
  ?creator dblp:primaryAffiliation ?string .
}

CONSTRUCT {
