CONSTRUCT {
  <https://dblp.org/rec/journals/oms/LiuLT16> dblp:authoredBy ?author .
  ?first_paper dblp:authoredBy ?author .
  ?first_paper dblp:yearOfPublication ?first_year .
}
WHERE {
  <https://dblp.org/rec/journals/oms/LiuLT16> dblp:authoredBy ?author .
  {
    SELECT ?author (MIN(?year) AS ?first_year) WHERE {
      <https://dblp.org/rec/journals/oms/LiuLT16> dblp:authoredBy ?author .
      ?any_paper dblp:authoredBy ?author .
      ?any_paper dblp:yearOfPublication ?year .
    } GROUP BY ?author
  }
  ?first_paper dblp:authoredBy ?author .
  ?first_paper dblp:yearOfPublication ?first_year .
}

