CONSTRUCT {
  ?paper dblp:authoredBy ?author .
}
WHERE {
  {
    SELECT ?author
    WHERE {
      <https://dblp.org/rec/conf/iscid/ZhangJ17> dblp:authoredBy ?author .
      ?paper dblp:authoredBy ?author .
    }
    GROUP BY ?author
    ORDER BY DESC(COUNT(?paper))
    LIMIT 1
  }
  ?paper dblp:authoredBy ?author .
}

