construct_query:
CONSTRUCT {
  <https://dblp.org/rec/journals/ijcv/CallariF01> dblp:authoredBy ?author .
  ?firstPaper dblp:authoredBy ?author .
  ?firstPaper dblp:yearOfPublication ?year .
}
WHERE {
  <https://dblp.org/rec/journals/ijcv/CallariF01> dblp:authoredBy ?author .
  {
    SELECT ?author (MIN(?allYears) AS ?year)
    WHERE {
      ?anyPaper dblp:authoredBy ?author .
      ?anyPaper dblp:yearOfPublication ?allYears .
    }
    GROUP BY ?author
  }
  ?firstPaper dblp:authoredBy ?author .
  ?firstPaper dblp:yearOfPublication ?year .
}

