construct_query:
CONSTRUCT {
  <https://dblp.org/rec/conf/kdd/JansenSK06> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
  ?paper dblp:yearOfPublication ?year .
}
WHERE {
  <https://dblp.org/rec/conf/kdd/JansenSK06> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
  ?paper dblp:yearOfPublication ?year .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  <https://dblp.org/rec/conf/seke/BryantBARO02> dblp:authoredBy ?authorWithMostFrequentAffiliation .
  ?authorWithMostFrequentAffiliation dblp:primaryAffiliation ?mostFrequentAffiliation .
}
WHERE {
  {
    SELECT ?mostFrequentAffiliation
    WHERE {
      {
        SELECT ?affiliation (COUNT(?author) AS ?count)
        WHERE {
          <https://dblp.org/rec/conf/seke/BryantBARO02> dblp:authoredBy ?author .
          ?author dblp:primaryAffiliation ?affiliation .
        }
        GROUP BY ?affiliation
        ORDER BY DESC(?count)
        LIMIT 1
      }
    }
  }
  <https://dblp.org/rec/conf/seke/BryantBARO02> dblp:authoredBy ?authorWithMostFrequentAffiliation .
  ?authorWithMostFrequentAffiliation dblp:primaryAffiliation ?mostFrequentAffiliation .
}

