construct_query:
CONSTRUCT {
    <https://dblp.org/rec/conf/ipmu/Fernandez-Bassso18> dblp:authoredBy ?author .
    ?paper dblp:authoredBy ?author .
}
WHERE {
    <https://dblp.org/rec/conf/ipmu/Fernandez-Bassso18> dblp:authoredBy ?author .
    ?paper dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/conf/cms/MerkelDV11> dblp:authoredBy ?author .
  ?publication dblp:authoredBy ?author .
}
WHERE {
  <https://dblp.org/rec/conf/cms/MerkelDV11> dblp:authoredBy ?author .
  ?publication dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/journals/access/GuoLLYY18> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
}
WHERE {
  {
    SELECT ?author WHERE {
      <https://dblp.org/rec/journals/access/GuoLLYY18> dblp:authoredBy ?author .
      ?paper dblp:authoredBy ?author .
    }
    GROUP BY ?author
    ORDER BY DESC(COUNT(?paper))
    LIMIT 1
  }
  ?paper dblp:authoredBy ?author .
}

CONSTRUCT {
    <https://dblp.org/rec/conf/cata/DaiL01> dblp:authoredBy ?author .
    ?paper dblp:authoredBy ?author .
    ?paper a dblp:Publication .
    ?author a dblp:Creator .
}
WHERE {
    {
        SELECT ?author WHERE {
            <https://dblp.org/rec/conf/cata/DaiL01> dblp:authoredBy ?author .
            ?paper dblp:authoredBy ?author .
        }
        GROUP BY ?author
        ORDER BY DESC(COUNT(?paper))
        LIMIT 1
    }
    ?paper dblp:authoredBy ?author .
    ?paper a dblp:Publication .
    ?author a dblp:Creator .
}

