construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
  <https://dblp.org/rec/conf/iconac/RenTWLLW19> dblp:yearOfPublication ?year1 .
  <https://dblp.org/rec/conf/icit2/RauCVG20> dblp:yearOfPublication ?year2 .
}
WHERE {
  <https://dblp.org/rec/conf/iconac/RenTWLLW19> dblp:yearOfPublication ?year1 .
  <https://dblp.org/rec/conf/icit2/RauCVG20> dblp:yearOfPublication ?year2 .
}

subgraph_ttl:
@prefix dblp: <https://dblp.org/rdf/schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://dblp.org/rec/conf/icit2/RauCVG20> dblp:yearOfPublication "2020"^^xsd:gYear .

<https://dblp.org/rec/conf/iconac/RenTWLLW19> dblp:yearOfPublication "2019"^^xsd:gYear .

construct_query:
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX cito: <http://purl.org/spar/cito/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX schema: <https://schema.org/>

CONSTRUCT {
  ?author dblp:primaryCreatorName ?authorName ;
          schema:numberOfPublications ?pubCount .
}
WHERE {
  {
    SELECT ?author (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      <https://dblp.org/rec/conf/lopstr/BasinDFHN04> dblp:authoredBy ?author .
      ?publication dblp:authoredBy ?author .
    }
    GROUP BY ?author
    ORDER BY DESC(?pubCount)
    LIMIT 1
  }
  ?author dblp:primaryCreatorName ?authorName .
}

