construct_query:
CONSTRUCT {
    <https://dblp.org/rec/conf/atal/NguyenRRRS16> dblp:authoredBy ?author .
    ?paper dblp:authoredBy ?author .
}
WHERE {
    {
        SELECT ?author WHERE {
            <https://dblp.org/rec/conf/atal/NguyenRRRS16> dblp:authoredBy ?author .
            ?p dblp:authoredBy ?author .
        }
        GROUP BY ?author
        ORDER BY DESC(COUNT(?p))
        LIMIT 1
    }
    ?paper dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/conf/embc/Cvetkovic13> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
}
WHERE {
  <https://dblp.org/rec/conf/embc/Cvetkovic13> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/journals/mr/ChoiKLJAKJPYCKK15> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
}
WHERE {
  <https://dblp.org/rec/journals/mr/ChoiKLJAKJPYCKK15> dblp:authoredBy ?author .
  ?paper dblp:authoredBy ?author .
}

CONSTRUCT {
  <https://dblp.org/rec/journals/eswa/ChenL09a> dblp:authoredBy ?author .
  ?firstPaper dblp:authoredBy ?author .
  ?firstPaper dblp:yearOfPublication ?minYear .
}
WHERE {
  {
    SELECT
      ?author
      (MIN(?year) AS ?minYear)
    WHERE {
      <https://dblp.org/rec/journals/eswa/ChenL09a> dblp:authoredBy ?author .
      ?paper dblp:authoredBy ?author .
      ?paper dblp:yearOfPublication ?year .
    }
    GROUP BY ?author
    ORDER BY ASC(?minYear)
    LIMIT 1
  }
  ?firstPaper dblp:authoredBy ?author .
  ?firstPaper dblp:yearOfPublication ?minYear .
}

